namespace Payments;

public sealed class PaymentGateway
{
    private readonly Dictionary<string, decimal> _charges = new();

    public Task<ChargeResult> ChargeAsync(string cardToken, decimal amount)
    {
        ArgumentNullException.ThrowIfNull(cardToken);

        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount must be positive.");

        if (amount > 10_000m)
            return Task.FromResult(new ChargeResult(string.Empty, Success: false, "Amount exceeds limit."));

        var chargeId = $"ch_{Guid.NewGuid():N}";
        _charges[chargeId] = amount;
        return Task.FromResult(new ChargeResult(chargeId, Success: true, Error: null));
    }

    public Task<RefundResult> RefundAsync(string chargeId)
    {
        ArgumentNullException.ThrowIfNull(chargeId);

        if (!_charges.Remove(chargeId, out var amount))
            return Task.FromResult(new RefundResult(string.Empty, Success: false, "Charge not found."));

        var refundId = $"re_{Guid.NewGuid():N}";
        return Task.FromResult(new RefundResult(refundId, Success: true, Error: null));
    }

    public WebhookResult ProcessWebhook(string eventType, string payload)
    {
        ArgumentNullException.ThrowIfNull(eventType);
        ArgumentNullException.ThrowIfNull(payload);

        if (string.IsNullOrWhiteSpace(payload))
            throw new ArgumentException("Payload cannot be empty.", nameof(payload));

        return eventType switch
        {
            "charge.succeeded" => new WebhookResult(Handled: true, eventType),
            "charge.failed" => new WebhookResult(Handled: true, eventType),
            "refund.created" => new WebhookResult(Handled: true, eventType),
            _ => new WebhookResult(Handled: false, eventType),
        };
    }
}

public record ChargeResult(string ChargeId, bool Success, string? Error = null);
public record RefundResult(string RefundId, bool Success, string? Error = null);
public record WebhookResult(bool Handled, string EventType);

