using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _gateway = new PaymentGateway();
    }

    // ── ChargeAsync ─────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessWithChargeId()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 50m);

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
        Assert.StartsWith("ch_", result.ChargeId);
        Assert.IsNull(result.Error);
    }

    [TestMethod]
    [DataRow(0.01)]
    [DataRow(1.00)]
    [DataRow(9999.99)]
    [DataRow(10_000.00)]
    public async Task ChargeAsync_BoundaryAmounts_Succeeds(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_valid", (decimal)amount);

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_AmountExceedsLimit_ReturnsFailure()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 10_001m);

        Assert.IsFalse(result.Success);
        Assert.AreEqual(string.Empty, result.ChargeId);
        Assert.IsNotNull(result.Error);
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRange(double amount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_NullCardToken_ThrowsArgumentNull()
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.ChargeAsync(null!, 10m));

        Assert.AreEqual("cardToken", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_MultipleCharges_ProduceUniqueIds()
    {
        var r1 = await _gateway.ChargeAsync("tok_a", 10m);
        var r2 = await _gateway.ChargeAsync("tok_b", 20m);

        Assert.AreNotEqual(r1.ChargeId, r2.ChargeId);
    }

    // ── RefundAsync ─────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ExistingCharge_ReturnsSuccessWithRefundId()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 25m);

        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(refund.Success);
        Assert.IsNotNull(refund.RefundId);
        Assert.StartsWith("re_", refund.RefundId);
        Assert.IsNull(refund.Error);
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentCharge_ReturnsFailure()
    {
        var result = await _gateway.RefundAsync("ch_doesnotexist");

        Assert.IsFalse(result.Success);
        Assert.AreEqual(string.Empty, result.RefundId);
        Assert.IsNotNull(result.Error);
    }

    [TestMethod]
    public async Task RefundAsync_SameChargeTwice_SecondRefundFails()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 50m);

        var first = await _gateway.RefundAsync(charge.ChargeId);
        var second = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(first.Success);
        Assert.IsFalse(second.Success);
    }

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentNull()
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.RefundAsync(null!));

        Assert.AreEqual("chargeId", ex.ParamName);
    }

    // ── ProcessWebhook ──────────────────────────────────────────

    [TestMethod]
    [DataRow("charge.succeeded")]
    [DataRow("charge.failed")]
    [DataRow("refund.created")]
    public void ProcessWebhook_KnownEvent_ReturnsHandled(string eventType)
    {
        var result = _gateway.ProcessWebhook(eventType, "{\"id\":\"evt_1\"}");

        Assert.IsTrue(result.Handled);
        Assert.AreEqual(eventType, result.EventType);
    }

    [TestMethod]
    [DataRow("unknown.event")]
    [DataRow("payout.sent")]
    public void ProcessWebhook_UnknownEvent_ReturnsNotHandled(string eventType)
    {
        var result = _gateway.ProcessWebhook(eventType, "{\"id\":\"evt_2\"}");

        Assert.IsFalse(result.Handled);
        Assert.AreEqual(eventType, result.EventType);
    }

    [TestMethod]
    public void ProcessWebhook_NullEventType_ThrowsArgumentNull()
    {
        Assert.ThrowsExactly<ArgumentNullException>(
            () => _gateway.ProcessWebhook(null!, "{}"));
    }

    [TestMethod]
    public void ProcessWebhook_NullPayload_ThrowsArgumentNull()
    {
        Assert.ThrowsExactly<ArgumentNullException>(
            () => _gateway.ProcessWebhook("charge.succeeded", null!));
    }

    [TestMethod]
    [DataRow("")]
    [DataRow("   ")]
    public void ProcessWebhook_EmptyOrWhitespacePayload_ThrowsArgument(string payload)
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook("charge.succeeded", payload));
    }
}

